#include <iostream>
#include <array>
#include <iomanip>

int main() {
    constexpr std::size_t response_count{40};
    constexpr std::size_t frequency_size{11}; // indices 0 to 10

    const std::array<int, response_count> responses{
        1, 2, 6, 4, 8, 5, 9, 7, 8, 10,
        1, 6, 3, 8, 6, 10, 3, 8, 2, 7, 6, 5, 7, 6, 8, 6, 7, 5, 6, 6,
        5, 6, 7, 5, 6, 4, 8, 6, 8, 10
    };

    std::array<int, frequency_size> frequency{}; // zero-initialized

    for (std::size_t answer{0}; answer < responses.size(); ++answer) {
        int rating{responses[answer]};
        if (rating >= 1 && rating < static_cast<int>(frequency.size())) {
            ++frequency[rating];
        }
    }

    std::cout << std::setw(6) << "Rating" << std::setw(17) << "Frequency" << '\n';
    for (std::size_t rating{1}; rating < frequency.size(); ++rating) {
        std::cout << std::setw(6) << rating 
                  << std::setw(17) << frequency[rating] << '\n';
    }

    return 0;
}

#include <iostream>
#include <array>
#include <iomanip>
#include <string>

int main() {
    // Part 1: Graphing array values with a histogram
    constexpr std::size_t size{5};
    const std::array<int, size> n{19, 3, 15, 7, 11};

    std::cout << std::setw(7) << "Element" 
              << std::setw(13) << "Value" 
              << std::setw(17) << "Histogram" << '\n';

    for (std::size_t i{0}; i < n.size(); ++i) {
        std::cout << std::setw(7) << i 
                  << std::setw(13) << n[i] << "        ";

        // Nested loop printing asterisks
        for (int j{1}; j <= n[i]; ++j) {
            std::cout << '*';
        }
        std::cout << '\n';
    }

    // Part 2: Deterministic simulation demonstrating direct indexing replacing switch
    constexpr std::size_t die_faces{7}; // index 1 to 6
    std::array<unsigned int, die_faces> die_frequency{};

    // Sample rolls representing die roll outcomes
    const std::array<int, 12> rolls{3, 6, 1, 2, 6, 5, 4, 6, 3, 2, 1, 6};
    for (int face : rolls) {
        ++die_frequency[face]; // Direct indexing: replaces switch entirely
    }

    std::cout << "\n" << std::setw(4) << "Face" << std::setw(17) << "Frequency" << '\n';
    for (std::size_t face{1}; face < die_frequency.size(); ++face) {
        std::cout << std::setw(4) << face 
                  << std::setw(17) << die_frequency[face] << '\n';
    }

    return 0;
}
